import 'package:flutter/material.dart';
class CartaoPeca extends StatelessWidget { final IconData icone; final String nome,situacao; final bool instalada; final VoidCallback onPressed; const CartaoPeca({super.key,required this.icone,required this.nome,required this.situacao,required this.instalada,required this.onPressed}); @override Widget build(BuildContext context)=>Card(color:instalada?Colors.green.shade100:Colors.grey.shade200,child:Padding(padding:const EdgeInsets.all(14),child:Column(children:[Icon(icone,size:48),Text(nome,style:const TextStyle(fontWeight:FontWeight.bold,fontSize:18)),Text(situacao),FilledButton(onPressed:onPressed,child:Text(instalada?'Remover':'Instalar'))]))); }
